#!/usr/bin/env bash
# Proves the k3s wrapper preserves node, capacity, registry, and network contracts.

# shellcheck disable=SC2310,SC2312
set -euo pipefail

subject_directory="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
subject="${subject_directory}/k3s-entrypoint.sh"
registry_hosts_source="${subject_directory}/hosts.toml"
fail() {
  printf '%s\n' "$1" >&2
  exit 1
}

run_wrapper() {
  local fixture_root="$1"
  local route_interface="$2"
  local existing_address="$3"
  local cpu_millicores="${4:-}"
  local system_cpu_millicores="${5:-}"
  local hosts_source="${6:-${registry_hosts_source}}"
  local fail_copy="${7:-false}"
  local memory_mib="${8:-}"
  local zone="${9-lh1-a}"
  local node_name="${10-deadbeefcafe}"
  local data_root="${11:-${fixture_root}/k3s-data}"
  local instance_type="${12:-}"
  local fake_bin="${fixture_root}/bin"
  local fake_cgroup="${fixture_root}/cgroup"
  local fake_proc_sys="${fixture_root}/proc/sys"
  local fake_hosts="${fixture_root}/etc/hosts"
  local preload_images_source="${fixture_root}/preload-images"
  local registries_path="${fixture_root}/etc/rancher/k3s/registries.yaml"
  local cp_binary
  local true_binary
  cp_binary="$(type -P cp)"
  true_binary="$(type -P true)"
  if [[ ! -e ${fake_hosts} ]]; then
    mkdir -p "${fixture_root}/etc"
    printf '127.0.0.1 localhost\n' >"${fake_hosts}"
  fi
  mkdir -p "${fake_bin}" "${fake_cgroup}" "${fake_proc_sys}/fs/inotify" \
    "${preload_images_source}" \
    "$(dirname "${registries_path}")"
  printf 'current dragonfly image\n' >"${preload_images_source}/dragonfly-sso.tar"
  printf 'current headscale image\n' >"${preload_images_source}/headscale-key-producer.tar"
  printf '128\n' >"${fake_proc_sys}/fs/inotify/max_user_instances"
  printf '# File generated by k3s. DO NOT EDIT.\n' >"${registries_path}"

  cat >"${fake_bin}/ip" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
printf '%s\n' "$*" >>"${TEST_IP_LOG}"
case "$*" in
  "-4 -o route show ${K3S_SHARED_IPV4_CIDR}")
    if [[ -n "${TEST_ROUTE_INTERFACE}" ]]; then
      printf '%s dev %s proto kernel scope link src 172.19.0.4\n' \
        "${K3S_SHARED_IPV4_CIDR}" "${TEST_ROUTE_INTERFACE}"
    fi
    ;;
  "-4 -o address show dev ${TEST_ROUTE_INTERFACE}")
    if [[ -n "${TEST_EXISTING_ADDRESS}" ]]; then
      printf '2: %s inet %s scope global %s\n' \
        "${TEST_ROUTE_INTERFACE}" "${TEST_EXISTING_ADDRESS}" \
        "${TEST_ROUTE_INTERFACE}"
    fi
    ;;
  "-4 address add ${K3S_NODE_IPV4_CIDR} dev ${TEST_ROUTE_INTERFACE}") ;;
  *) exit 64 ;;
esac
EOF
  cat >"${fake_bin}/cp" <<'EOF'
#!/usr/bin/env bash
set -euo pipefail
if [[ "${TEST_FAIL_COPY}" == "true" ]]; then
  printf 'partial content\n' >"$2"
  exit 73
fi
exec "${TEST_CP}" "$@"
EOF
  cat >"${fake_bin}/k3s" <<'EOF'
#!/usr/bin/env bash
printf 'GOMAXPROCS=%s\n' "${GOMAXPROCS:-}" >"${TEST_K3S_ENV_LOG}"
printf '%s\n' "$@" >"${TEST_K3S_LOG}"
EOF
  cat >"${fake_bin}/hostname" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "${TEST_NODE_NAME}"
EOF
  cat >"${fake_bin}/mdev" <<'EOF'
#!/usr/bin/env bash
printf '%s\n' "$*" >>"${TEST_MDEV_LOG}"
EOF
  cat >"${fake_bin}/mount" <<'EOF'
#!/usr/bin/env bash
if [[ "${TEST_FAIL_MOUNT}" == "true" ]]; then
  exit 32
fi
EOF
  cat >"${fake_bin}/awk" <<'EOF'
#!/usr/bin/env bash
if [[ "${1:-}" == *MemTotal* ]]; then
  printf '%s\n' "${TEST_MEMORY_KIB}"
  exit 0
fi
if [[ "${1:-}" == *processor* ]]; then
  printf '%s\n' "${TEST_CPU_MILLICORES}"
  exit 0
fi
exec "${TEST_AWK}" "$@"
EOF
  chmod +x \
    "${fake_bin}/awk" \
    "${fake_bin}/cp" \
    "${fake_bin}/hostname" \
    "${fake_bin}/ip" \
    "${fake_bin}/k3s" \
    "${fake_bin}/mdev" \
    "${fake_bin}/mount"
  ln -sf "${true_binary}" "${fake_bin}/sleep"
  printf '%s\n' "${TEST_MOUNTINFO:-}" >"${fixture_root}/mountinfo"

  local -a env_args=(
    K3S_DATA_DIR="${data_root}"
    K3S_BINARY="${fake_bin}/k3s"
    K3S_CGROUP_ROOT="${fake_cgroup}"
    K3S_HOSTS_PATH="${fake_hosts}"
    K3S_NODE_IPV4_CIDR="172.19.255.10/16"
    K3S_POD_IPV4_CIDR="10.240.0.0/16"
    K3S_SERVICE_IPV4_CIDR="172.31.0.0/20"
    K3S_SHARED_IPV4_CIDR="172.19.0.0/16"
    K3S_ZONE="${zone}"
    K3S_PROC_SYS_ROOT="${fake_proc_sys}"
    K3S_MOUNTINFO_PATH="${fixture_root}/mountinfo"
    K3S_PRELOAD_IMAGES_SOURCE="${preload_images_source}"
    K3S_REGISTRY_HOSTS_SOURCE="${hosts_source}"
    K3S_REGISTRIES_PATH="${registries_path}"
    K3S_TOKEN_WEBHOOK_PATH="${fixture_root}/etc/token-webhook.yaml"
    CLUSTER_NAME="${TEST_CLUSTER_NAME:-cell-eaws-lh1}"
    TEST_EXISTING_ADDRESS="${existing_address}"
    TEST_AWK="$(type -P awk)"
    TEST_CP="${cp_binary}"
    TEST_FAIL_COPY="${fail_copy}"
    TEST_FAIL_MOUNT="${TEST_FAIL_MOUNT:-false}"
    TEST_IP_LOG="${fixture_root}/ip.log"
    TEST_K3S_ENV_LOG="${fixture_root}/k3s-env.log"
    TEST_K3S_LOG="${fixture_root}/k3s.log"
    TEST_MDEV_LOG="${fixture_root}/mdev.log"
    TEST_MEMORY_KIB="${TEST_MEMORY_KIB:-43049040}"
    TEST_CPU_MILLICORES="${TEST_CPU_MILLICORES:-14000}"
    TEST_NODE_NAME="${node_name}"
    TEST_ROUTE_INTERFACE="${route_interface}"
    PATH="${fake_bin}:${PATH}"
  )
  [[ -n ${instance_type} ]] && env_args+=(K3S_INSTANCE_TYPE="${instance_type}")
  [[ -n ${cpu_millicores} ]] && env_args+=(K3S_CPU_MILLICORES="${cpu_millicores}")
  [[ -n ${memory_mib} ]] && env_args+=(K3S_MEMORY_MIB="${memory_mib}")
  [[ -n ${system_cpu_millicores} ]] && env_args+=(K3S_SYSTEM_CPU_MILLICORES="${system_cpu_millicores}")

  local -a cmd_args=(server)
  if [[ $# -ge 13 ]]; then
    cmd_args+=("${@:13}")
  fi

  env "${env_args[@]}" sh "${subject}" "${cmd_args[@]}"
}

test_deduplicates_caller_cidr_flags() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 "" "" "" "${registry_hosts_source}" false "" "lh1-a" "deadbeefcafe" \
    "${fixture_root}/k3s-data" "" "--cluster-cidr=10.42.0.0/16" "--service-cidr=172.31.0.0/20"

  test "$(grep -Fxc -- '--cluster-cidr=10.240.0.0/16' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "wrapper did not retain the authoritative cluster CIDR exactly once"
  test "$(grep -Fxc -- '--service-cidr=172.31.0.0/20' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "wrapper did not retain the authoritative service CIDR exactly once"
  if grep -Fq -- '--cluster-cidr=10.42.0.0/16' "${fixture_root}/k3s.log"; then
    fail "wrapper leaked caller-provided cluster CIDR flag to k3s"
  fi
}

test_removes_floci_registry_mirror_before_k3s() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  [[ ! -e "${fixture_root}/etc/rancher/k3s/registries.yaml" ]] \
    || fail "wrapper left Floci's headerless registry mirror active"
}

test_preserves_dragonfly_registry_header_contract() {
  grep -Fxq 'server = "http://origin-registry:5000/v2"' "${registry_hosts_source}" \
    || fail "registry hosts lost the native HTTP origin fallback"
  grep -Fxq '[host."http://127.0.0.1:4001"]' "${registry_hosts_source}" \
    || fail "registry hosts lost the Dragonfly proxy endpoint"
  grep -Fxq 'capabilities = ["pull", "resolve"]' "${registry_hosts_source}" \
    || fail "registry hosts lost the Dragonfly pull capabilities"
  grep -Fxq '[host."http://127.0.0.1:4001".header]' "${registry_hosts_source}" \
    || fail "registry hosts lost the Dragonfly header table"
  test "$(grep -Fxc 'X-Dragonfly-Registry = ["http://origin-registry:5000"]' "${registry_hosts_source}" || true)" -eq 1 \
    || fail "registry hosts must provide exactly one native HTTP origin header"
  if grep -Fq '[host."http://origin-registry:5000"]' "${registry_hosts_source}"; then
    fail "registry hosts must not add a headerless origin mirror"
  fi
}

test_materializes_registry_hosts_for_retained_volume() {
  local acceptance_directory
  local acceptance_target
  local fixture_root
  local hosts_directory
  local hosts_link
  local hosts_target
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN
  acceptance_directory="${fixture_root}/k3s-data/agent/etc/containerd/certs.d/127.0.0.1:15100"
  acceptance_target="${acceptance_directory}/hosts.toml"
  hosts_directory="${fixture_root}/k3s-data/agent/etc/containerd/certs.d/localhost:15100"
  hosts_link="${fixture_root}/materialized-hosts.toml"
  hosts_target="${hosts_directory}/hosts.toml"

  mkdir -p "${hosts_directory}"
  printf 'stale retained content\n' >"${hosts_target}"
  chmod 0600 "${hosts_target}"

  run_wrapper "${fixture_root}" eth7 ""

  cmp "${registry_hosts_source}" "${acceptance_target}" >/dev/null \
    || fail "wrapper did not materialize the owned acceptance registry hosts"
  [[ "$(find "${acceptance_target}" -prune -perm 0444 -print)" == "${acceptance_target}" ]] \
    || fail "wrapper did not make acceptance registry hosts read-only"
  [[ "$(find "${acceptance_directory}" -prune -perm 0700 -print)" == "${acceptance_directory}" ]] \
    || fail "wrapper did not restrict the acceptance registry hosts directory"
  cmp "${registry_hosts_source}" "${hosts_target}" >/dev/null \
    || fail "wrapper did not replace retained registry hosts content"
  [[ "$(find "${hosts_target}" -prune -perm 0444 -print)" == "${hosts_target}" ]] \
    || fail "wrapper did not make registry hosts content read-only"
  [[ "$(find "${hosts_directory}" -prune -perm 0700 -print)" == "${hosts_directory}" ]] \
    || fail "wrapper did not restrict the registry hosts directory"
  if find "${hosts_directory}" -name 'hosts.toml.tmp.*' -print -quit | grep -q .; then
    fail "wrapper left a partial registry hosts file visible"
  fi

  ln "${hosts_target}" "${hosts_link}"
  chmod 0644 "${hosts_target}"
  run_wrapper "${fixture_root}" eth7 ""

  [[ ${hosts_target} -ef ${hosts_link} ]] \
    || fail "wrapper replaced an unchanged registry hosts file"
  [[ "$(find "${hosts_target}" -prune -perm 0444 -print)" == "${hosts_target}" ]] \
    || fail "wrapper did not restore registry hosts permissions idempotently"
}

test_fails_closed_without_registry_hosts_source() {
  local fixture_root
  local hosts_directory
  local hosts_target
  local registries_path
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN
  hosts_directory="${fixture_root}/k3s-data/agent/etc/containerd/certs.d/localhost:15100"
  hosts_target="${hosts_directory}/hosts.toml"
  registries_path="${fixture_root}/etc/rancher/k3s/registries.yaml"

  mkdir -p "${hosts_directory}"
  printf 'retained content\n' >"${hosts_target}"
  if run_wrapper "${fixture_root}" eth7 "" 4000 1000 \
    "${fixture_root}/missing-hosts.toml" >"${fixture_root}/stdout" 2>"${fixture_root}/stderr"; then
    fail "wrapper started k3s without its registry hosts source"
  fi

  grep -Fq 'The immutable containerd hosts configuration is unavailable' "${fixture_root}/stderr" \
    || fail "wrapper did not explain the missing registry hosts source"
  [[ "$(<"${hosts_target}")" == "retained content" ]] \
    || fail "wrapper damaged retained registry content after materialization failed"
  [[ "$(<"${registries_path}")" == "# File generated by k3s. DO NOT EDIT." ]] \
    || fail "wrapper removed Floci's usable mirror before materialization succeeded"
  [[ ! -e "${fixture_root}/k3s.log" ]] \
    || fail "wrapper invoked k3s after registry materialization failed"
}

test_keeps_retained_hosts_when_atomic_copy_fails() {
  local fixture_root
  local hosts_directory
  local hosts_target
  local registries_path
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN
  hosts_directory="${fixture_root}/k3s-data/agent/etc/containerd/certs.d/localhost:15100"
  hosts_target="${hosts_directory}/hosts.toml"
  registries_path="${fixture_root}/etc/rancher/k3s/registries.yaml"

  mkdir -p "${hosts_directory}"
  printf 'retained content\n' >"${hosts_target}"
  if run_wrapper "${fixture_root}" eth7 "" 4000 1000 \
    "${registry_hosts_source}" true >"${fixture_root}/stdout" 2>"${fixture_root}/stderr"; then
    fail "wrapper started k3s after its atomic registry copy failed"
  fi

  [[ "$(<"${hosts_target}")" == "retained content" ]] \
    || fail "wrapper exposed partial registry content after a copy failure"
  if find "${hosts_directory}" -name 'hosts.toml.tmp.*' -print -quit | grep -q .; then
    fail "wrapper retained its failed temporary registry hosts file"
  fi
  [[ "$(<"${registries_path}")" == "# File generated by k3s. DO NOT EDIT." ]] \
    || fail "wrapper removed Floci's usable mirror after an atomic copy failure"
  [[ ! -e "${fixture_root}/k3s.log" ]] \
    || fail "wrapper invoked k3s after its atomic registry copy failed"
}

test_raises_the_shared_inotify_instance_limit() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  [[ "$(<"${fixture_root}/proc/sys/fs/inotify/max_user_instances")" == "1024" ]] \
    || fail "wrapper did not raise the shared inotify instance limit"
}

test_materializes_dynamic_loop_devices() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  diff -u <(printf '%s\n' '-d' '-s') "${fixture_root}/mdev.log" \
    || fail "wrapper did not watch and scan for dynamic loop devices"
}

test_rejects_failed_csi_mount_propagation() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  if TEST_FAIL_MOUNT=true run_wrapper "${fixture_root}" eth7 ""; then
    fail "wrapper started k3s without CSI mount propagation"
  fi
  [[ ! -e "${fixture_root}/k3s.log" ]] \
    || fail "wrapper invoked k3s after CSI mount propagation failed"
}

test_enables_mutable_pv_node_affinity() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  test "$(grep -Fxc -- '--kube-apiserver-arg=feature-gates=MutablePVNodeAffinity=true' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "wrapper did not enable mutable PV affinity in the API server"
  test "$(grep -Fxc -- '--kubelet-arg=feature-gates=MutablePVNodeAffinity=true' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "wrapper did not enable mutable PV affinity in kubelet"
}

test_disables_single_server_leader_election() {
  local fixture_root
  local flag
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  for flag in \
    '--kube-cloud-controller-manager-arg=leader-elect=false' \
    '--kube-controller-manager-arg=leader-elect=false' \
    '--kube-scheduler-arg=leader-elect=false'; do
    test "$(grep -Fxc -- "${flag}" "${fixture_root}/k3s.log" || true)" -eq 1 \
      || fail "wrapper did not disable single-server leader election with ${flag}"
  done
}

test_disables_anonymous_auth() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  test "$(grep -Fxc -- '--kube-apiserver-arg=anonymous-auth=false' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "wrapper did not disable kube-apiserver anonymous authentication"
}

test_enables_protect_kernel_defaults() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  test "$(grep -Fxc -- '--protect-kernel-defaults=true' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "wrapper did not enable protect-kernel-defaults"
}

test_advertises_rawfile_topology_without_zone() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 "" 4000 1000 \
    "${registry_hosts_source}" false 12288 ""

  test "$(grep -Fxc -- '--node-label=hostname=deadbeefcafe' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "control runtime did not advertise exactly one Rawfile topology label"
  test "$(grep -Fxc -- '--node-name=deadbeefcafe' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "control runtime did not use its retained node identity"
  if grep -Fq -- '--node-label=topology.kubernetes.io/zone=' "${fixture_root}/k3s.log"; then
    fail "control runtime advertised a cell zone"
  fi
}

test_persists_node_identity_across_container_recreation() {
  local first_container_root
  local node_identity_path
  local retained_data_root
  local second_container_root
  first_container_root="$(mktemp -d)"
  second_container_root="$(mktemp -d)"
  retained_data_root="$(mktemp -d)"
  trap 'rm -rf "${first_container_root}" "${second_container_root}" "${retained_data_root}"' RETURN
  node_identity_path="${retained_data_root}/.floci-node-name"

  run_wrapper "${first_container_root}" eth7 "" 4000 1000 \
    "${registry_hosts_source}" false 12288 lh1-a deadbeefcafe "${retained_data_root}"

  [[ "$(<"${node_identity_path}")" == "deadbeefcafe" ]] \
    || fail "wrapper did not persist the initial node identity"
  [[ "$(find "${node_identity_path}" -prune -perm 0400 -print)" == "${node_identity_path}" ]] \
    || fail "wrapper did not restrict the retained node identity"
  grep -Fxq -- '--node-name=deadbeefcafe' "${first_container_root}/k3s.log" \
    || fail "first container did not pass its persisted node identity to k3s"

  run_wrapper "${second_container_root}" eth7 "" 4000 1000 \
    "${registry_hosts_source}" false 12288 lh1-a facefeed1234 "${retained_data_root}"

  [[ "$(<"${node_identity_path}")" == "deadbeefcafe" ]] \
    || fail "replacement container changed the retained node identity"
  grep -Fxq -- '--node-name=deadbeefcafe' "${second_container_root}/k3s.log" \
    || fail "replacement container did not reuse the retained node identity"
  grep -Fxq -- '--node-label=hostname=deadbeefcafe' "${second_container_root}/k3s.log" \
    || fail "replacement container changed Rawfile node affinity identity"
  if grep -Fq -- 'facefeed1234' "${second_container_root}/k3s.log"; then
    fail "replacement container leaked its transient hostname into k3s identity"
  fi
}

test_rejects_noncanonical_node_name() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  if run_wrapper "${fixture_root}" eth7 "" 4000 1000 \
    "${registry_hosts_source}" false 12288 "" "not-a-node" \
    >"${fixture_root}/stdout" 2>"${fixture_root}/stderr"; then
    fail "wrapper started k3s with a noncanonical node name"
  fi

  grep -Fq 'The container hostname must be 12 lowercase hexadecimal characters' \
    "${fixture_root}/stderr" \
    || fail "wrapper did not explain the noncanonical node name"
  [[ ! -e "${fixture_root}/k3s.log" ]] \
    || fail "wrapper invoked k3s with a noncanonical node name"
}

test_rejects_corrupt_retained_node_identity() {
  local fixture_root
  local node_identity_path
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN
  node_identity_path="${fixture_root}/k3s-data/.floci-node-name"
  mkdir -p "$(dirname "${node_identity_path}")"
  printf 'deadbeefcafe-corrupt\n' >"${node_identity_path}"

  if run_wrapper "${fixture_root}" eth7 "" >"${fixture_root}/stdout" 2>"${fixture_root}/stderr"; then
    fail "wrapper started k3s with a corrupt retained node identity"
  fi

  grep -Fq 'The retained node identity must contain exactly 12 lowercase hexadecimal characters' \
    "${fixture_root}/stderr" \
    || fail "wrapper did not explain the corrupt retained node identity"
  [[ "$(<"${node_identity_path}")" == "deadbeefcafe-corrupt" ]] \
    || fail "wrapper replaced the corrupt retained node identity"
  [[ ! -e "${fixture_root}/k3s.log" ]] \
    || fail "wrapper invoked k3s with a corrupt retained node identity"
}

test_requires_node_identity_backfill_for_retained_k3s_state() {
  local fixture_root
  local node_identity_path
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN
  node_identity_path="${fixture_root}/k3s-data/.floci-node-name"
  mkdir -p "${fixture_root}/k3s-data/server/db"

  if run_wrapper "${fixture_root}" eth7 "" >"${fixture_root}/stdout" 2>"${fixture_root}/stderr"; then
    fail "wrapper derived a new identity for retained K3s state"
  fi

  grep -Fq "The retained K3s data volume requires a node identity backfill at ${node_identity_path}" \
    "${fixture_root}/stderr" \
    || fail "wrapper did not require a safe node identity backfill"
  [[ ! -e ${node_identity_path} ]] \
    || fail "wrapper seeded retained K3s state from a replacement container hostname"
  [[ ! -e "${fixture_root}/k3s.log" ]] \
    || fail "wrapper invoked k3s without the retained node identity backfill"
}

test_advertises_exact_cpu_shares() {
  local fixture_root
  local cpu_millicores
  local system_cpu_millicores
  local kubelet_reserve
  local gomaxprocs

  while read -r cpu_millicores system_cpu_millicores kubelet_reserve gomaxprocs; do
    fixture_root="$(mktemp -d)"
    run_wrapper "${fixture_root}" eth7 "" "${cpu_millicores}" "${system_cpu_millicores}"

    grep -Fq -- "--kubelet-arg=system-reserved=cpu=${kubelet_reserve}m," "${fixture_root}/k3s.log" \
      || fail "wrapper rounded the ${cpu_millicores}m node share"
    grep -Fxq -- "GOMAXPROCS=${gomaxprocs}" "${fixture_root}/k3s-env.log" \
      || fail "wrapper did not bound Go concurrency for the ${cpu_millicores}m node share"
    rm -rf "${fixture_root}"
  done <<'EOF'
3750 750 11000 3
5000 1000 10000 5
8000 1000 7000 8
EOF
}

test_rejects_memory_share_without_daemon_reserve() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  if run_wrapper "${fixture_root}" eth7 "" 4000 1000 \
    "${registry_hosts_source}" false 2048 >"${fixture_root}/stdout" 2>"${fixture_root}/stderr"; then
    fail "wrapper started k3s without memory reserved for its daemons"
  fi

  grep -Fq 'K3S_MEMORY_MIB must exceed the k3s daemon memory reserve' "${fixture_root}/stderr" \
