test_discovers_reassigned_interface() {
  local fixture_root
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  run_wrapper "${fixture_root}" eth7 ""

  grep -Fxq -- '-4 address add 172.19.255.10/16 dev eth7' "${fixture_root}/ip.log" \
    || fail "wrapper did not bind the durable address to the discovered interface"
  if grep -Fq -- 'route replace' "${fixture_root}/ip.log"; then
    fail "wrapper installed dead inter-cluster routes"
  fi
  grep -Fxq -- '--node-ip=172.19.255.10' "${fixture_root}/k3s.log" \
    || fail "wrapper did not publish the durable node IP"
  grep -Fxq -- '--flannel-iface=eth7' "${fixture_root}/k3s.log" \
    || fail "wrapper retained a fixed Docker interface"
  grep -Fxq -- '--node-label=topology.kubernetes.io/zone=lh1-a' "${fixture_root}/k3s.log" \
    || fail "wrapper did not advertise the node zone"
  grep -Fxq -- '--node-label=node.kubernetes.io/instance-type=m5.large' "${fixture_root}/k3s.log" \
    || fail "wrapper did not advertise the node instance type"
  grep -Fxq -- '--node-label=topology.kubernetes.io/region=us-west-2' "${fixture_root}/k3s.log" \
    || fail "wrapper did not advertise the node region"
  grep -Fxq -- '--node-label=karpenter.sh/capacity-type=on-demand' "${fixture_root}/k3s.log" \
    || fail "wrapper did not advertise the on-demand capacity type"
  test "$(grep -Fxc -- '--node-label=hostname=deadbeefcafe' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "cell runtime did not advertise exactly one Rawfile topology label"
  test "$(grep -Fxc -- '--node-name=deadbeefcafe' "${fixture_root}/k3s.log" || true)" -eq 1 \
    || fail "cell runtime did not use its retained node identity"
  grep -Fxq -- '--kubelet-arg=fail-swap-on=true' "${fixture_root}/k3s.log" \
    || fail "wrapper did not keep pod swap disabled"
  grep -Fxq -- '--snapshotter=stargz' "${fixture_root}/k3s.log" \
    || fail "wrapper did not select k3s's built-in stargz snapshotter"
  if grep -Fq -- 'stargz-runtime' "${fixture_root}/k3s.log"; then
    fail "wrapper exposed the built-in snapshotter through custom node metadata"
  fi
  if grep -Fq -- 'image-service-endpoint' "${fixture_root}/k3s.log"; then
    fail "wrapper bypassed k3s's built-in stargz lifecycle"
  fi
  local expected_eviction_available_kib
  local expected_reserved_kib
  expected_eviction_available_kib=$((43049040 - 8192 * 1024 + 1024 * 1024))
  expected_reserved_kib=$((2048 * 1024))
  grep -Fxq -- "--kubelet-arg=eviction-hard=memory.available<${expected_eviction_available_kib}Ki,nodefs.available<20%,imagefs.available<20%" "${fixture_root}/k3s.log" \
    || fail "wrapper did not evict workloads before the child cgroup memory limit"
  grep -Fxq -- "--kubelet-arg=eviction-minimum-reclaim=nodefs.available=2%,imagefs.available=2%" "${fixture_root}/k3s.log" \
    || fail "wrapper did not configure eviction minimum reclaim threshold"
  grep -Fxq -- '--kubelet-arg=image-gc-high-threshold=60' "${fixture_root}/k3s.log" \
    || fail "wrapper did not configure image garbage collection high threshold"
  grep -Fxq -- '--kubelet-arg=image-gc-low-threshold=40' "${fixture_root}/k3s.log" \
    || fail "wrapper did not configure image garbage collection low threshold"
  grep -Fxq -- "--kubelet-arg=system-reserved=cpu=13000m,memory=${expected_reserved_kib}Ki" "${fixture_root}/k3s.log" \
    || fail "wrapper did not reserve memory for k3s and containerd inside the child limit"
  grep -Fxq -- "GOMAXPROCS=2" "${fixture_root}/k3s-env.log" \
    || fail "wrapper did not bound k3s Go concurrency to the CPU share"
}

