test_partitions_shared_vm_capacity_across_both_local_clusters() {
  local fixture_root memory_kib role reserved_cpu reserved_memory eviction_memory
  local total_memory total_cpu ctrl_memory cell_memory expected_cpu small_memory=0
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN

  for memory_kib in 32796796 65536000; do
    total_memory=0
    total_cpu=0
    for role in ctrl cell; do
      mkdir -p "${fixture_root}/${role}"
      TEST_MOUNTINFO="floci-aws-openplex-local-eks-${role}-eaws-lh1" \
        TEST_MEMORY_KIB="${memory_kib}" \
        run_wrapper "${fixture_root}/${role}" eth7 ""
      reserved_cpu="$(sed -n 's/^--kubelet-arg=system-reserved=cpu=\([0-9]*\)m,.*$/\1/p' "${fixture_root}/${role}/k3s.log")"
      reserved_memory="$(sed -n 's/^--kubelet-arg=system-reserved=.*memory=\([0-9]*\)Ki$/\1/p' "${fixture_root}/${role}/k3s.log")"
      eviction_memory="$(sed -n 's/^--kubelet-arg=eviction-hard=memory.available<\([0-9]*\)Ki,.*$/\1/p' "${fixture_root}/${role}/k3s.log")"
      total_cpu=$((total_cpu + 14000 - reserved_cpu))
      total_memory=$((total_memory + memory_kib - reserved_memory - eviction_memory))
      if [[ ${role} == ctrl ]]; then
        ctrl_memory=$((memory_kib - reserved_memory - eviction_memory))
      else
        cell_memory=$((memory_kib - reserved_memory - eviction_memory))
      fi
      expected_cpu=7000
      [[ ${role} != cell ]] || expected_cpu=6000
      [[ $((14000 - reserved_cpu)) -eq ${expected_cpu} ]] \
        || fail "local node did not receive its asymmetric Pod CPU allocation"
      grep -Fxq "GOMAXPROCS=$((expected_cpu / 1000))" "${fixture_root}/${role}/k3s-env.log" \
        || fail "local node concurrency exceeded its VM CPU allocation"
    done
    [[ ${total_cpu} -eq 13000 ]] || fail "local schedulers double-counted VM CPUs"
    [[ ${total_memory} -le $((memory_kib - 7 * 1024 * 1024)) ]] \
      || fail "local schedulers double-counted memory or consumed reserved headroom"
    [[ ${ctrl_memory} -gt ${cell_memory} ]] || fail "control node did not retain its larger share"
    if [[ ${small_memory} -eq 0 ]]; then
      small_memory="${total_memory}"
      [[ ${total_memory} -ge $((24 * 1024 * 1024)) ]] || fail "default VM lost its 24 GiB Pod budget"
    else
      [[ ${total_memory} -gt $((small_memory * 2)) ]] || fail "larger VM capacity remained artificially capped"
    fi
  done
}

test_scales_asymmetric_cpu_shares_without_losing_or_duplicating_capacity() {
  local fixture_root host_cpu role reserved_cpu pod_cpu total_cpu ctrl_cpu=0
  fixture_root="$(mktemp -d)"
  trap 'rm -rf "${fixture_root}"' RETURN
  for host_cpu in 2000 8000 16000 28000; do
    total_cpu=0
    for role in ctrl cell; do
      mkdir -p "${fixture_root}/${role}"
      TEST_MOUNTINFO="floci-aws-openplex-local-eks-${role}-eaws-lh1" \
        TEST_CPU_MILLICORES="${host_cpu}" \
        run_wrapper "${fixture_root}/${role}" eth7 ""
      reserved_cpu="$(sed -n 's/^--kubelet-arg=system-reserved=cpu=\([0-9]*\)m,.*$/\1/p' "${fixture_root}/${role}/k3s.log")"
      pod_cpu=$((host_cpu - reserved_cpu))
      [[ ${pod_cpu} -gt 0 ]] || fail "local node lost all Pod CPU headroom"
      total_cpu=$((total_cpu + pod_cpu))
      if [[ ${role} == ctrl ]]; then
        ctrl_cpu="${pod_cpu}"
      else
        [[ ${ctrl_cpu} -gt ${pod_cpu} ]] || fail "control node lost its larger CPU share"
        # Integer rounding gives the cell at most one additional millicore.
        [[ $((pod_cpu * 7 - ctrl_cpu * 6)) -ge 0 && $((pod_cpu * 7 - ctrl_cpu * 6)) -lt 13 ]] \
          || fail "local CPU split diverged from the 7:6 allocation"
      fi
    done
    [[ ${total_cpu} -eq $((host_cpu - 1000)) ]] || fail "CPU partition lost capacity or consumed system reserves"
  done
}

