      >"${fixture_root}/stdout" 2>"${fixture_root}/stderr"; then
      fail "local node accepted an override beyond its shared ${resource} allocation"
    fi
    [[ ! -e ${fixture_root}/k3s.log ]] || fail "overcommitted local node started k3s"
  done
}

